style.css:
/* Deixa o fundo da barra de pesquisa transparente */
input[name="q"] {
    background-color: transparent !important;  /* Fundo transparente */
    border: 1px solid #ccc !important;  /* Borda sutil ao redor da barra */
    color: #333 !important;  /* Cor do texto */
    padding: 10px !important;  /* Espaçamento interno */
    font-size: 16px !important;  /* Tamanho da fonte */
    border-radius: 5px !important;  /* Bordas arredondadas */
}

/* Estilo do botão de pesquisa */
input[type="submit"] {
    background-color: #4CAF50 !important;  /* Cor verde para o botão */
    color: white !important;  /* Texto branco no botão */
    border: none !important;  /* Remove a borda */
    padding: 10px 20px !important;  /* Espaçamento interno */
    border-radius: 5px !important;  /* Bordas arredondadas */
    cursor: pointer !important;  /* Cursor de mão ao passar o mouse */
}

/* Altera a cor do botão de pesquisa ao passar o mouse */
input[type="submit"]:hover {
    background-color: #45a049 !important;  /* Cor um pouco mais escura ao passar o mouse */
}
